import assert from 'node:assert/strict';
import {createRequire,syncBuiltinESMExports} from 'node:module';
import {resolve,join} from 'node:path';
import {createHash} from 'node:crypto';
import {ForgeHost} from './src/adapters/bmad/forge.ts';
const fs=createRequire(import.meta.url)('node:fs/promises');
const original={lstat:fs.lstat,realpath:fs.realpath,readdir:fs.readdir};
const template=await original.lstat('.');
const root=resolve('C:/audit-memory'),base=join(root,'output','initiative-test');
const cases=[];
for(const mode of ['stable','stable-absent','junction','identity','mtime','ctime','appearance','disappearance']){
 let changed=false,afterChecks=0,missingReads=0,returnedDirectoryReads=0;
 const missing=()=>Object.assign(Error('synthetic absence'),{code:'ENOENT'});
 const stats=(path)=>{
  const altered=changed&&path===base;
  return Object.assign(Object.create(Object.getPrototypeOf(template)),template,{
   dev:1,ino:path===base?100+(altered&&mode==='identity'?1:0):10,
   mode:altered&&mode==='junction'?0o120777:0o40755,nlink:2,
   size:0,mtimeMs:100+(altered&&mode==='mtime'?1:0),
   ctimeMs:100+(altered&&mode==='ctime'?1:0)
  });
 };
 fs.lstat=async path=>{
  if(path===base){
   if(changed)afterChecks++;
   if(mode==='stable-absent'||mode==='appearance'&&!changed){
    missingReads++;
    if(mode==='appearance'&&missingReads===2)changed=true;
    throw missing();
   }
   if(mode==='disappearance'&&changed)throw missing();
  }
  return stats(path);
 };
 fs.realpath=async path=>changed&&mode==='junction'&&path===base?resolve('C:/outside-audit'):path;
 fs.readdir=async path=>{if(path===base){returnedDirectoryReads++;if(['junction','identity','mtime','ctime','disappearance'].includes(mode))changed=true;}return [];};
 syncBuiltinESMExports();
 try{
  const host=new ForgeHost({rootPath:root,forge:{outputBase:base,initiativeId:'initiative-test',contextDigest:''}},new AbortController().signal);
  host.assert=async()=>{};host.resolved.add('workflow');host.resolved.add('config');
  const receipts=[];host.bind(async value=>receipts.push(value));
  let result=null,errorCode=null,errorName=null;
  try{result=JSON.parse(await host.execute({kind:'check-sessions'},'audit-'+mode,'audit-turn'));}
  catch(error){errorCode=error.code??null;errorName=error.name;}
  const stable=mode.startsWith('stable');
  if(stable){
   assert.equal(errorCode,null);assert.equal(result.observed,true);assert.equal(receipts.length,1);
   assert.equal(result.locations[1].exists,mode==='stable');
   assert.equal(result.locations.every(p=>p.sessions.length===0),true);
  }else{
   assert.equal(changed,true);assert.ok(afterChecks>0);assert.equal(errorCode,'OUTPUT_REFUSED');assert.equal(errorName,'Error');
   assert.equal(receipts.length,0);assert.equal(host.sessionsChecked,false);
  }
  cases.push({mode,passed:true,changed,afterChecks,missingReads,returnedDirectoryReads,errorCode,errorName,observedReceiptCount:receipts.length,result});
 }finally{Object.assign(fs,original);syncBuiltinESMExports();}
}
const sourceSha256={};
for(const path of ['src/adapters/bmad/forge.ts','src/adapters/codex/dialogue.ts','tests/forge.test.mjs']){
 sourceSha256[path]=createHash('sha256').update(await fs.readFile(path)).digest('hex');
}
console.log(JSON.stringify({checkedAt:new Date().toISOString(),sourceSha256,cases},null,2));
